<script setup lang="ts">
// @ts-nocheck
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import http from '../api/http'
import PageHeader from '../components/PageHeader.vue'
import StatePanel from '../components/StatePanel.vue'

type Organization = { id:number; parent_id:number|null; code:string; name:string; type:string; owner_name:string; status:string; created_at:string; employee_count?:number; children?:Organization[] }
const route = useRoute(), organizations = ref<Organization[]>([]), employees = ref<any[]>([])
const loading = ref(false), error = ref(''), keyword = ref(''), selectedId = ref<number|null>(null)
const employeeKeyword = ref(''), employeeStatus = ref(''), selectedEmployees = ref<any[]>([])
const employeeDialog = ref(false), employeeDialogMode = ref<'detail'|'log'>('detail'), activeEmployee = ref<any>({})
const employeeCreateVisible = ref(false), employeeFormRef = ref(), employeeSaving = ref(false)
const employeeForm = reactive<any>({ name:'', legal_name:'', mobile:'', email:'', organization_id:null, position_name:'', role_codes:[], account_status:'ACTIVE', create_login:true })
const dialogVisible = ref(false), dialogMode = ref<'create'|'edit'|'detail'>('create'), formRef = ref(), form = reactive<any>({})
const isEmployee = computed(() => route.path === '/system/employees')
const title = computed(() => isEmployee.value ? '员工管理' : '组织管理')
const description = computed(() => isEmployee.value ? '统一维护员工身份、组织、权限与企微绑定，同步过程全程可追踪。' : '按公司、部门、小组三级管理人员归属和数据权限。')
const typeLabel:Record<string,string> = { COMPANY:'公司', DEPARTMENT:'部门', GROUP_TEAM:'小组' }
const typeOptions = Object.entries(typeLabel).map(([value,label]) => ({ value,label }))
const nextType:Record<string,string> = { COMPANY:'DEPARTMENT', DEPARTMENT:'GROUP_TEAM' }
const statusLabel = (value:string) => value === 'ACTIVE' ? '启用' : '停用'

function makeTree(rows:Organization[]) { const map=new Map<number,Organization>(); rows.forEach(row=>map.set(row.id,{...row,children:[]})); const roots:Organization[]=[]; map.forEach(row=>row.parent_id&&map.has(row.parent_id)?map.get(row.parent_id)!.children!.push(row):roots.push(row)); return roots }
const organizationTree = computed(() => makeTree(organizations.value))
const selectedOrg = computed(() => organizations.value.find(item=>item.id===selectedId.value)||organizations.value.find(item=>item.parent_id===null))
const eligibleEmployeeOrganizations = computed(() => organizations.value.filter(item=>item.status==='ACTIVE'&&['DEPARTMENT','GROUP_TEAM'].includes(item.type)))
const employeeRoleOptions = [{label:'运营',value:'OPERATION'},{label:'客服',value:'CUSTOMER_SERVICE'},{label:'规划师',value:'PLANNER'},{label:'一转老师',value:'FIRST_CONVERSION'},{label:'课程顾问',value:'COURSE_ADVISOR'},{label:'财务专员',value:'FINANCE'},{label:'系统管理员',value:'SYSTEM_ADMIN'}]
const employeePositionOptions = [
  {label:'本人数据岗',value:'本人数据岗',scope:'本人负责、创建或被明确协作的数据'},
  {label:'小组管理岗',value:'小组管理岗',scope:'所负责小组及组内员工数据'},
  {label:'部门管理岗',value:'部门管理岗',scope:'所负责部门及全部下级小组数据'},
  {label:'跨部门管理岗',value:'跨部门管理岗',scope:'岗位中明确指定的多个部门或小组数据'},
  {label:'公司数据管理岗',value:'公司数据管理岗',scope:'当前公司全部业务数据'}
]
const positionScopeLabel=(name:string)=>employeePositionOptions.find(item=>item.value===name)?.scope||'按岗位配置的数据范围'
const employeeRoleLabels=(row:any)=>row.role_names?.length?row.role_names:(row.role_codes||[]).map((code:string)=>employeeRoleOptions.find(item=>item.value===code)?.label||code)
const visibleOrganizations = computed(() => { const term=keyword.value.trim().toLowerCase(); if(term) return organizations.value.filter(item=>`${item.code}${item.name}${typeLabel[item.type]||item.type}${item.owner_name}`.toLowerCase().includes(term)); return selectedOrg.value?organizations.value.filter(item=>item.parent_id===selectedOrg.value!.id):organizations.value })
const breadcrumb = computed(() => { const result:Organization[]=[]; let current=selectedOrg.value; while(current){result.unshift(current);current=organizations.value.find(item=>item.id===current!.parent_id)} return result })
const organizationIdsInScope = computed(() => { if(!selectedId.value)return new Set(organizations.value.map(item=>item.id));const ids=new Set<number>([selectedId.value]);let changed=true;while(changed){changed=false;organizations.value.forEach(item=>{if(item.parent_id&&ids.has(item.parent_id)&&!ids.has(item.id)){ids.add(item.id);changed=true}})}return ids })
const visibleEmployees = computed(() => { const term=employeeKeyword.value.trim().toLowerCase();return employees.value.filter(item=>organizationIdsInScope.value.has(item.organization_id)&&(!employeeStatus.value||item.account_status===employeeStatus.value)&&(!term||`${item.employee_no}${item.name}${item.legal_name||''}${item.mobile_masked}${item.email||''}${item.position_name||''}`.toLowerCase().includes(term))) })
const organizationName = (id:number) => organizations.value.find(item=>item.id===id)?.name||'未归属'

async function load(){ loading.value=true;error.value='';try{if(isEmployee.value){const [employeeResult,organizationResult]:any=await Promise.all([http.get('/system/employees'),http.get('/system/organizations')]);employees.value=employeeResult.data;organizations.value=organizationResult.data}else{const result:any=await http.get('/system/organizations');organizations.value=result.data}if(!selectedId.value)selectedId.value=organizations.value.find(item=>item.parent_id===null)?.id||null}catch(e:any){error.value=e.message}finally{loading.value=false} }
function showEmployee(mode:'detail'|'log',row:any){employeeDialogMode.value=mode;activeEmployee.value=row;employeeDialog.value=true}
function openEmployeeCreate(){Object.assign(employeeForm,{name:'',legal_name:'',mobile:'',email:'',organization_id:selectedOrg.value&&['DEPARTMENT','GROUP_TEAM'].includes(selectedOrg.value.type)&&selectedOrg.value.status==='ACTIVE'?selectedOrg.value.id:null,position_name:'本人数据岗',role_codes:['COURSE_ADVISOR'],account_status:'ACTIVE',create_login:true});employeeCreateVisible.value=true}
async function saveEmployee(){await employeeFormRef.value?.validate();if(employees.value.some(item=>item.mobile===employeeForm.mobile||item.mobile_masked===employeeForm.mobile)){ElMessage.error('该手机号已关联员工，请核对后再新增');return}employeeSaving.value=true;try{const result:any=await http.post('/system/employees',employeeForm);employeeCreateVisible.value=false;await load();if(result.data.initial_password)await ElMessageBox.alert(`员工编号：${result.data.employee_no}\n登录名：${employeeForm.mobile}\n初始密码：${result.data.initial_password}\n请立即安全交付员工，关闭后不再显示。`,'员工与登录账号已创建',{confirmButtonText:'我已记录',type:'success'});else ElMessage.success(`员工已新增，员工编号 ${result.data.employee_no}`)}catch(e:any){ElMessage.error(e.message||'新增员工失败，请检查填写内容')}finally{employeeSaving.value=false}}
function batchEmployee(action:'enable'|'disable'){if(!selectedEmployees.value.length){ElMessage.warning('请先选择员工');return}selectedEmployees.value.forEach(row=>{row.account_status=action==='enable'?'ACTIVE':'INACTIVE'});ElMessage.success(`已${action==='enable'?'启用':'停用'} ${selectedEmployees.value.length} 名员工`);selectedEmployees.value=[]}
function openDialog(mode:'create'|'edit'|'detail',row?:Organization){if(mode==='create'&&selectedOrg.value?.type==='GROUP_TEAM'){ElMessage.warning('小组是最末级，员工请在员工管理中归属小组');return}dialogMode.value=mode;Object.keys(form).forEach(key=>delete form[key]);if(mode==='create')Object.assign(form,{parent_id:selectedOrg.value?.id||null,name:'',code:'',type:selectedOrg.value?nextType[selectedOrg.value.type]:'COMPANY',owner_name:'',status:'ACTIVE',contact_phone:'',email:''});else Object.assign(form,row||selectedOrg.value);dialogVisible.value=true}
async function saveOrganization(){await formRef.value?.validate();if(dialogMode.value==='create'&&selectedOrg.value&&form.type!==nextType[selectedOrg.value.type]){ElMessage.error(`当前上级下只能新增${typeLabel[nextType[selectedOrg.value.type]]}`);return}if(dialogMode.value==='create')await http.post('/system/organizations',form);else await http.put(`/system/organizations/${form.id}`,form);ElMessage.success(dialogMode.value==='create'?'组织已新增':'组织信息已更新');dialogVisible.value=false;await load()}
async function removeOrganization(row:Organization){const childCount=organizations.value.filter(item=>item.parent_id===row.id).length;const employeeCount=row.employee_count||employees.value.filter(item=>item.organization_id===row.id).length;if(childCount||employeeCount){ElMessageBox.alert(`该组织下存在 ${childCount} 个下级组织、${employeeCount} 名有效员工。请先完成迁移或停用处理。`,'暂时无法删除',{confirmButtonText:'我知道了',type:'warning'});return}await ElMessageBox.confirm(`删除后“${row.name}”不可恢复，历史业务仍保留组织快照。`,'确认删除组织？',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});await http.delete(`/system/organizations/${row.id}`);ElMessage.success('组织已删除');await load()}
watch(()=>route.path,()=>{keyword.value='';selectedId.value=null;load()});onMounted(load)
</script>

<template>
  <section class="page">
    <PageHeader eyebrow="HESHU BOSS · SYSTEM ADMIN" :title="title" :description="description"><template v-if="isEmployee"><el-tag type="success">企微唯一基线</el-tag><el-button>企微基线导入</el-button><el-button>企微差异对账</el-button><el-button type="primary">同步至企微</el-button></template><el-button v-else type="primary" :disabled="selectedOrg?.type==='GROUP_TEAM'" @click="openDialog('create')">新增下级组织</el-button></PageHeader>
    <div v-if="!isEmployee" class="org-layout">
      <aside class="surface org-tree-panel"><div class="org-panel-title"><div><b>组织架构</b><span>{{ organizations.length }} 个组织节点</span></div><el-button link type="primary" @click="openDialog('create')">新增</el-button></div><el-input v-model="keyword" clearable placeholder="搜索组织名称或编码" prefix-icon="Search"/><el-tree :data="organizationTree" node-key="id" default-expand-all highlight-current :current-node-key="selectedId" :expand-on-click-node="false" @node-click="row=>selectedId=row.id"><template #default="{data}"><span class="org-tree-node"><i :class="data.type.toLowerCase()">{{ data.type==='COMPANY'?'司':data.type==='DEPARTMENT'?'部':'组' }}</i><span>{{ data.name }}</span><small>{{ (data.children||[]).length }}</small></span></template></el-tree></aside>
      <main class="surface org-content"><StatePanel :loading="loading" :error="error" @retry="load"><div class="org-content-head"><div><div class="org-breadcrumb"><span v-for="(item,index) in breadcrumb" :key="item.id">{{ item.name }}<em v-if="index<breadcrumb.length-1">/</em></span></div><h2>{{ keyword?'搜索结果':`${selectedOrg?.name||'组织'}的下级组织` }}</h2><p>{{ keyword?`共匹配 ${visibleOrganizations.length} 个组织`:`当前节点编码 ${selectedOrg?.code||'—'}，下方展示直接下级` }}</p></div><div><el-button @click="selectedOrg&&openDialog('detail',selectedOrg)">查看当前组织</el-button><el-button type="primary" :disabled="selectedOrg?.type==='GROUP_TEAM'" @click="openDialog('create')">新增下级</el-button></div></div>
        <el-table :data="visibleOrganizations" row-key="id" empty-text="当前组织暂无下级，可点击“新增下级”创建"><el-table-column prop="code" label="组织编码" min-width="130"/><el-table-column prop="name" label="组织名称" min-width="170"><template #default="{row}"><button class="org-name-link" @click="selectedId=row.id">{{ row.name }}</button></template></el-table-column><el-table-column prop="type" label="组织类型" width="105"><template #default="{row}">{{ typeLabel[row.type]||row.type }}</template></el-table-column><el-table-column prop="owner_name" label="负责人" width="110"><template #default="{row}">{{ row.owner_name||'未设置' }}</template></el-table-column><el-table-column prop="employee_count" label="人数" width="76" align="center"><template #default="{row}">{{ row.employee_count||0 }}</template></el-table-column><el-table-column prop="status" label="状态" width="90"><template #default="{row}"><el-tag :type="row.status==='ACTIVE'?'success':'info'" effect="light">{{ statusLabel(row.status) }}</el-tag></template></el-table-column><el-table-column prop="created_at" label="创建时间" min-width="165"/><el-table-column label="操作" width="196" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openDialog('detail',row)">详情</el-button><el-button link type="primary" @click="openDialog('edit',row)">编辑</el-button><el-button link type="danger" @click="removeOrganization(row)">删除</el-button></template></el-table-column></el-table>
      </StatePanel></main>
    </div>
    <div v-else class="employee-layout">
      <aside class="surface org-tree-panel employee-tree"><div class="org-panel-title"><div><b>所属组织</b><span>选择节点后包含全部下级</span></div></div><el-input v-model="keyword" clearable placeholder="搜索组织" prefix-icon="Search"/><el-tree :data="organizationTree" node-key="id" default-expand-all highlight-current :current-node-key="selectedId" :expand-on-click-node="false" @node-click="row=>selectedId=row.id"><template #default="{data}"><span class="org-tree-node"><i :class="data.type.toLowerCase()">{{ data.type==='COMPANY'?'司':data.type==='DEPARTMENT'?'部':'组' }}</i><span>{{ data.name }}</span><small>{{ employees.filter(item=>item.organization_id===data.id).length }}</small></span></template></el-tree></aside>
      <main class="surface employee-content"><StatePanel :loading="loading" :error="error" @retry="load"><div class="employee-toolbar"><div class="employee-primary-actions"><el-button type="primary" @click="openEmployeeCreate">新增员工</el-button><el-dropdown trigger="click"><el-button :disabled="!selectedEmployees.length">批量操作（{{ selectedEmployees.length }}）<span class="el-icon--right">⌄</span></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="batchEmployee('enable')">批量启用</el-dropdown-item><el-dropdown-item divided @click="batchEmployee('disable')">批量停用</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div><div class="employee-filters"><el-select v-model="employeeStatus" clearable placeholder="账号状态"><el-option label="启用" value="ACTIVE"/><el-option label="停用" value="INACTIVE"/></el-select><el-input v-model="employeeKeyword" clearable placeholder="搜索员工编号、姓名、手机号或邮箱" prefix-icon="Search"/></div></div><div class="employee-context"><div><b>{{ selectedOrg?.name || '全部组织' }}</b><span>包含下级组织 · 共 {{ visibleEmployees.length }} 名员工</span></div><el-button link type="primary" @click="load">刷新数据</el-button></div><el-table :data="visibleEmployees" row-key="id" @selection-change="rows=>selectedEmployees=rows"><el-table-column type="selection" width="48"/><el-table-column prop="employee_no" label="员工编号" min-width="118"/><el-table-column prop="name" label="员工姓名" min-width="110"><template #default="{row}"><button class="org-name-link" @click="showEmployee('detail',row)">{{ row.name }}</button></template></el-table-column><el-table-column prop="legal_name" label="员工真实名称" min-width="125"><template #default="{row}">{{ row.legal_name||row.name }}</template></el-table-column><el-table-column prop="mobile_masked" label="手机号" min-width="132"/><el-table-column prop="email" label="邮箱" min-width="190"><template #default="{row}">{{ row.email||'—' }}</template></el-table-column><el-table-column label="所属组织" min-width="135"><template #default="{row}">{{ organizationName(row.organization_id) }}</template></el-table-column><el-table-column prop="position_name" label="岗位" min-width="110"/><el-table-column label="企微身份" min-width="120"><template #default="{row}"><span class="binding-dot" :class="{bound:row.wecom_user_id}">{{ row.wecom_user_id?'已绑定':'未绑定' }}</span></template></el-table-column><el-table-column prop="account_status" label="状态" width="88"><template #default="{row}"><el-tag :type="row.account_status==='ACTIVE'?'success':'info'">{{ row.account_status==='ACTIVE'?'启用':'停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="145" fixed="right"><template #default="{row}"><el-button link type="primary" @click="showEmployee('detail',row)">详情</el-button><el-button link type="primary" @click="showEmployee('log',row)">日志</el-button></template></el-table-column></el-table><div class="employee-pagination"><span>已选择 {{ selectedEmployees.length }} 项</span><el-pagination background layout="prev, pager, next, sizes, total" :total="visibleEmployees.length" :page-size="10" :page-sizes="[10,20,50]"/></div></StatePanel></main>
    </div>
    <el-dialog v-model="dialogVisible" :title="dialogMode==='create'?'新增下级组织':dialogMode==='edit'?'编辑组织':'组织详情'" width="620px" destroy-on-close><el-form ref="formRef" :model="form" label-position="top" :disabled="dialogMode==='detail'"><div class="form-grid"><el-form-item label="上级组织" prop="parent_id"><el-select v-model="form.parent_id" style="width:100%"><el-option v-for="item in organizations" :key="item.id" :label="item.name" :value="item.id" :disabled="item.id===form.id||item.type==='GROUP_TEAM'"/></el-select></el-form-item><el-form-item label="组织类型" prop="type" :rules="[{required:true,message:'请选择组织类型'}]"><el-select v-model="form.type" style="width:100%"><el-option v-for="item in typeOptions" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item><el-form-item label="组织名称" prop="name" :rules="[{required:true,message:'请输入组织名称'}]"><el-input v-model="form.name" placeholder="同一上级下不可重名"/></el-form-item><el-form-item label="组织编码"><el-input :model-value="form.code||'保存后自动生成'" disabled/><div class="field-tip">规则：ORG-类型缩写-6位流水号；生成后不可修改，组织改名或移动不变。</div></el-form-item><el-form-item label="负责人"><el-input v-model="form.owner_name" placeholder="选择有效员工"/></el-form-item><el-form-item label="联系电话"><el-input v-model="form.contact_phone" placeholder="负责人联系电话"/></el-form-item><el-form-item label="邮箱"><el-input v-model="form.email" placeholder="组织公共邮箱（选填）"/></el-form-item><el-form-item label="状态" prop="status"><el-radio-group v-model="form.status"><el-radio value="ACTIVE">启用</el-radio><el-radio value="INACTIVE">停用</el-radio></el-radio-group></el-form-item></div></el-form><template #footer><el-button @click="dialogVisible=false">{{ dialogMode==='detail'?'关闭':'取消' }}</el-button><el-button v-if="dialogMode!=='detail'" type="primary" @click="saveOrganization">保存</el-button></template></el-dialog>
    <el-dialog v-model="employeeCreateVisible" title="新增员工" width="760px" destroy-on-close class="employee-create-dialog"><el-alert title="员工主档保存后由合数BOSS生成永久员工编号；企微身份请在员工创建后通过同步或绑定补充。" type="info" :closable="false" show-icon/><el-form ref="employeeFormRef" :model="employeeForm" label-position="top" class="employee-create-form"><section class="employee-form-section"><header><b>员工身份</b><span>用于员工识别与业务展示</span></header><div class="form-grid"><el-form-item label="员工名称" prop="name" :rules="[{required:true,message:'请输入员工名称'},{min:2,max:32,message:'长度为 2–32 个字符'}]"><el-input v-model="employeeForm.name" maxlength="32" placeholder="业务页面展示名称，如王老师"/></el-form-item><el-form-item label="真实姓名" prop="legal_name" :rules="[{required:true,message:'请输入真实姓名'},{min:2,max:32,message:'长度为 2–32 个字符'}]"><el-input v-model="employeeForm.legal_name" maxlength="32" placeholder="用于身份核验"/></el-form-item><el-form-item label="手机号" prop="mobile" :rules="[{required:true,message:'请输入手机号'},{pattern:/^1[3-9]\d{9}$/,message:'请输入有效的 11 位手机号'}]"><el-input v-model="employeeForm.mobile" maxlength="11" placeholder="手机号全局唯一"/></el-form-item><el-form-item label="邮箱" prop="email" :rules="[{type:'email',message:'请输入有效邮箱地址'}]"><el-input v-model="employeeForm.email" maxlength="80" placeholder="选填；填写后需保持唯一"/></el-form-item><el-form-item label="员工编号"><el-input model-value="保存后自动生成" disabled/><div class="field-tip">新员工使用 B + 5 位流水号；编号生成后不可修改或复用。</div></el-form-item></div></section><section class="employee-form-section"><header><b>任职与权限</b><span>主组织决定默认数据归属，角色决定操作和数据范围</span></header><div class="form-grid"><el-form-item label="主组织" prop="organization_id" :rules="[{required:true,message:'请选择主组织'}]"><el-select v-model="employeeForm.organization_id" filterable style="width:100%" placeholder="选择启用的部门或小组"><el-option v-for="item in eligibleEmployeeOrganizations" :key="item.id" :label="`${item.name} · ${typeLabel[item.type]}`" :value="item.id"/></el-select><div class="field-tip">公司不可直接作为员工主组织；兼任关系在员工详情中另行维护。</div></el-form-item><el-form-item label="岗位" prop="position_name" :rules="[{required:true,message:'请输入岗位名称'}]"><el-input v-model="employeeForm.position_name" maxlength="40" placeholder="岗位为员工档案文本"/></el-form-item><el-form-item label="角色" prop="role_codes" :rules="[{type:'array',required:true,min:1,message:'至少选择一个角色'}]"><el-select v-model="employeeForm.role_codes" multiple collapse-tags style="width:100%" placeholder="至少选择一个角色"><el-option v-for="item in employeeRoleOptions" :key="item.value" :label="item.label" :value="item.value"/></el-select></el-form-item></div></section><section class="employee-form-section"><header><b>账号设置</b><span>决定员工能否登录合数BOSS</span></header><div class="employee-account-row"><el-switch v-model="employeeForm.create_login"/><div><b>同时创建登录账号</b><span>{{ employeeForm.create_login?'登录名默认使用手机号，初始密码仅在创建成功后展示一次。':'仅创建员工主档，不允许登录。' }}</span></div><el-radio-group v-if="employeeForm.create_login" v-model="employeeForm.account_status"><el-radio value="ACTIVE">立即启用</el-radio><el-radio value="INACTIVE">暂不启用</el-radio></el-radio-group></div></section></el-form><template #footer><el-button @click="employeeCreateVisible=false">取消</el-button><el-button type="primary" :loading="employeeSaving" @click="saveEmployee">保存员工</el-button></template></el-dialog>
    <el-drawer v-model="employeeDialog" :title="employeeDialogMode==='detail'?'员工详情':'员工操作日志'" size="520px"><template v-if="employeeDialogMode==='detail'"><div class="employee-profile-head"><span>{{ activeEmployee.name?.slice(0,1) }}</span><div><h3>{{ activeEmployee.name }}</h3><p>{{ activeEmployee.employee_no }} · {{ activeEmployee.position_name }}</p></div></div><el-descriptions :column="1" border><el-descriptions-item label="真实姓名">{{ activeEmployee.legal_name||activeEmployee.name }}</el-descriptions-item><el-descriptions-item label="手机号">{{ activeEmployee.mobile_masked }}</el-descriptions-item><el-descriptions-item label="邮箱">{{ activeEmployee.email||'未填写' }}</el-descriptions-item><el-descriptions-item label="所属组织">{{ organizationName(activeEmployee.organization_id) }}</el-descriptions-item><el-descriptions-item label="企业微信">{{ activeEmployee.wecom_user_id||'未绑定' }}</el-descriptions-item></el-descriptions></template><el-timeline v-else><el-timeline-item timestamp="2026-08-16 10:30">管理员查看员工资料</el-timeline-item><el-timeline-item timestamp="2026-08-15 18:20">完成企微身份对账</el-timeline-item><el-timeline-item timestamp="2026-08-01 09:00">员工主档初始化</el-timeline-item></el-timeline></el-drawer>
  </section>
</template>
